class Solution { public int[] spiralOrder(int[][] matrix) { java.util.ArrayList<Integer> list=new java.util.ArrayList<>();if(matrix.length==0||matrix[0].length==0)return new int[0];int t=0,b=matrix.length-1,l=0,r=matrix[0].length-1;while(t<=b&&l<=r){for(int j=l;j<=r;j++)list.add(matrix[t][j]);t++;for(int i=t;i<=b;i++)list.add(matrix[i][r]);r--;if(t<=b){for(int j=r;j>=l;j--)list.add(matrix[b][j]);b--;}if(l<=r){for(int i=b;i>=t;i--)list.add(matrix[i][l]);l++;}}int[] out=new int[list.size()];for(int i=0;i<out.length;i++)out[i]=list.get(i);return out; } }
